/**
 * exporter.js
 * Handles all export operations:
 *
 * Client-side (no server round-trip):
 *  - .txt  — plain text animation file with frame separators
 *  - .json — structured JSON frame data
 *  - .sh   — self-contained bash playback script
 *  - clipboard — copy the terminal play command
 *
 * Server-side (posts ASCII data to /api/export/prepare):
 *  - Returns download links for server-generated files
 */

// ── Bash Script Template ──────────────────────────────────────────
/**
 * Generate a self-contained bash playback script client-side.
 * Mirrors the server-side scriptGenerator for offline use.
 *
 * @param {Array<{ ascii: string, delay: number }>} frames
 * @param {object} meta
 * @returns {string}
 */
function buildBashScript(frames, meta = {}) {
  const {
    gifName      = 'animation',
    defaultFps   = 10,
    densityPreset = 'standard',
    asciiWidth   = 80,
  } = meta;

  const now = new Date().toISOString();

  // Build frame variable declarations using bash heredoc syntax.
  // Each frame is stored as FRAME_N using printf to avoid heredoc quoting issues.
  const frameVars = frames.map((f, i) => {
    // Escape single quotes in frame content for $'...' ANSI-C quoting
    const escaped = f.ascii
      .replace(/\\/g, '\\\\')
      .replace(/'/g, "\\'")
      .replace(/\n/g, '\\n');
    return `FRAME_${i}=$'${escaped}'`;
  }).join('\n');

  const frameArray = frames.map((_, i) => `  "$FRAME_${i}"`).join('\n');
  const delayArray = frames.map((f) => `  "${((f.delay || 100) / 1000).toFixed(4)}"`).join('\n');

  return `#!/usr/bin/env bash
# ═══════════════════════════════════════════════════════════════════
#  ASCII Terminal GIF Player — Self-Contained
#  Generated by ASCII Terminal GIF Converter
#
#  Source  : ${gifName}
#  Frames  : ${frames.length}
#  Width   : ${asciiWidth} cols
#  Density : ${densityPreset}
#  Date    : ${now}
#
#  Usage   : ./play_ascii.sh [fps] [loops]
#    fps   - Playback speed override (default: ${defaultFps})
#    loops - Number of times to loop; 0 = infinite (default: 0)
#
#  Compatibility: bash 3.2+, Linux, macOS, WSL
# ═══════════════════════════════════════════════════════════════════

set -euo pipefail

OVERRIDE_FPS="\${1:-0}"
MAX_LOOPS="\${2:-0}"

hide_cursor()  { printf '\\033[?25l'; }
show_cursor()  { printf '\\033[?25h'; }
reset_attrs()  { printf '\\033[0m'; }
set_green()    { printf '\\033[32m'; }
move_home()    { printf '\\033[H'; }
clear_screen() { printf '\\033[2J\\033[H'; }

cleanup() { show_cursor; reset_attrs; printf '\\n'; exit 0; }
trap cleanup INT TERM EXIT

command -v bc >/dev/null 2>&1 || { echo "ERROR: 'bc' is required. Install it and retry."; exit 1; }

# ── Frame Data ─────────────────────────────────────────────────────
${frameVars}

FRAMES=(
${frameArray}
)

DELAYS=(
${delayArray}
)

TOTAL=${frames.length}

# ── Playback Loop ──────────────────────────────────────────────────
hide_cursor
clear_screen

loop_count=0

while true; do
  [[ $MAX_LOOPS -gt 0 && $loop_count -ge $MAX_LOOPS ]] && break

  for (( i=0; i<TOTAL; i++ )); do
    move_home
    set_green
    printf '%s' "\${FRAMES[$i]}"
    reset_attrs

    if [[ "$OVERRIDE_FPS" != "0" ]] && [[ "$OVERRIDE_FPS" =~ ^[0-9]+(\\.?[0-9]*)$ ]]; then
      D=$(echo "scale=6; 1 / $OVERRIDE_FPS" | bc)
    else
      D="\${DELAYS[$i]}"
    fi

    sleep "$D"
  done

  (( loop_count++ )) || true
done

cleanup
`;
}

// ── TXT Export ────────────────────────────────────────────────────
function buildTXTContent(frames, meta = {}) {
  const { gifName = 'animation', asciiWidth = 80 } = meta;
  const sep = '─'.repeat(asciiWidth);

  const header = [
    `# ASCII Terminal GIF Export`,
    `# Source   : ${gifName}`,
    `# Frames   : ${frames.length}`,
    `# Width    : ${asciiWidth} cols`,
    `# Generated: ${new Date().toISOString()}`,
    '',
  ].join('\n');

  const body = frames.map((f, i) =>
    `${sep}\n# FRAME ${String(i).padStart(4, '0')} | delay=${f.delay}ms\n${sep}\n${f.ascii}`
  ).join('\n\n');

  return header + body;
}

// ── JSON Export ───────────────────────────────────────────────────
function buildJSONContent(frames, meta = {}) {
  return JSON.stringify({
    version:     '1.0.0',
    generator:   'ASCII Terminal GIF Converter',
    generatedAt: new Date().toISOString(),
    meta: {
      gifName:      meta.gifName || 'animation',
      frameCount:   frames.length,
      asciiWidth:   meta.asciiWidth || 80,
      asciiHeight:  meta.asciiHeight || 24,
      densityPreset: meta.densityPreset || 'standard',
      mode:          meta.mode || 'grayscale',
    },
    frames: frames.map((f, i) => ({
      index: i,
      delay: f.delay,
      ascii: f.ascii,
    })),
  }, null, 2);
}

// ── Download Trigger ──────────────────────────────────────────────
function triggerDownload(content, filename, mimeType = 'text/plain') {
  const blob = new Blob([content], { type: mimeType });
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement('a');
  a.href     = url;
  a.download = filename;
  a.style.display = 'none';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  // Revoke after a short delay to allow the download to start
  setTimeout(() => URL.revokeObjectURL(url), 10_000);
}

// ── Exporter Class ────────────────────────────────────────────────
export class Exporter {
  constructor() {
    this.frames       = [];   // { ascii, coloredHtml, delay }
    this.meta         = {};   // gifName, asciiWidth, asciiHeight, densityPreset, mode, fps
    this.exportSession = null; // Server-side export session
  }

  /** Load frames and meta for export. */
  setData(frames, meta) {
    this.frames       = frames;
    this.meta         = meta;
    this.exportSession = null; // Invalidate previous server export on new data
  }

  /** Export as plain-text .txt file. */
  exportTXT() {
    if (!this._hasFrames()) return;
    const content  = buildTXTContent(this.frames, this.meta);
    const filename = this._baseName() + '.txt';
    triggerDownload(content, filename, 'text/plain;charset=utf-8');
  }

  /** Export as JSON file. */
  exportJSON() {
    if (!this._hasFrames()) return;
    const content  = buildJSONContent(this.frames, this.meta);
    const filename = this._baseName() + '.json';
    triggerDownload(content, filename, 'application/json');
  }

  /** Export as bash playback script. */
  exportSH() {
    if (!this._hasFrames()) return;
    const content  = buildBashScript(this.frames, this.meta);
    const filename = 'play_ascii.sh';
    triggerDownload(content, filename, 'application/x-sh');
  }

  /** Copy the terminal playback command to clipboard. */
  async copyCommand() {
    const cmd = 'chmod +x play_ascii.sh && ./play_ascii.sh';
    try {
      await navigator.clipboard.writeText(cmd);
      return cmd;
    } catch {
      // Fallback for HTTP contexts
      const ta = document.createElement('textarea');
      ta.value = cmd;
      ta.style.position = 'fixed';
      ta.style.opacity  = '0';
      document.body.appendChild(ta);
      ta.select();
      document.execCommand('copy');
      document.body.removeChild(ta);
      return cmd;
    }
  }

  /**
   * Send frames to the server, which generates export files and returns
   * download links. Useful for large frame sets or CI/automation contexts.
   *
   * @returns {Promise<{ txt, json, sh }>} Server download URLs
   */
  async prepareServerExport() {
    if (!this._hasFrames()) throw new Error('No frames to export.');

    // Only send ascii + delay to server (skip coloredHtml to reduce payload)
    const payload = {
      frames: this.frames.map((f) => ({ ascii: f.ascii, delay: f.delay })),
      meta:   this.meta,
    };

    const res = await fetch('/api/export/prepare', {
      method:  'POST',
      headers: { 'Content-Type': 'application/json' },
      body:    JSON.stringify(payload),
    });

    if (!res.ok) {
      const body = await res.json().catch(() => ({}));
      throw new Error(body.error || `Server error ${res.status}`);
    }

    const data = await res.json();
    this.exportSession = data;
    return data;
  }

  // ── Helpers ────────────────────────────────────────────────────

  _hasFrames() {
    if (!this.frames.length) {
      console.warn('[Exporter] No frames loaded. Convert a GIF first.');
      return false;
    }
    return true;
  }

  _baseName() {
    const name = (this.meta.gifName || 'animation').replace(/\.gif$/i, '').replace(/\s+/g, '_');
    return `ascii_${name}`;
  }
}
